// ─── Geography: approximate coordinates, road distance = great circle x 1.3 ──
const CITY_COORDS = {
  'Conakry': [9.51, -13.71], 'Kankan': [10.38, -9.31], 'Labé': [11.32, -12.28],
  'Nzérékoré': [7.75, -8.82], 'Kindia': [10.06, -12.86], 'Boké': [10.94, -14.30],
  'Faranah': [10.04, -10.74], 'Mamou': [10.38, -12.09], 'Siguiri': [11.42, -9.17],
  'Kamsar': [10.65, -14.61], 'Fria': [10.37, -13.58], 'Macenta': [8.54, -9.47],
  'Dabola': [10.75, -11.11], 'Forécariah': [9.43, -13.09], 'Télimélé': [10.90, -13.03],
  'Kissidougou': [9.18, -10.10], 'Coyah': [9.70, -13.38], 'Boffa': [10.18, -14.04],
  'Sangarédi': [11.13, -13.79], 'Dubréka': [9.79, -13.52], 'Mambia': [9.93, -13.04],
};
const DUT_CITIES = Object.keys(CITY_COORDS).sort((a, b) => a.localeCompare(b, 'fr'));

const geoKm = (a, b) => {
  const A = CITY_COORDS[a], B = CITY_COORDS[b];
  if (!A || !B) return 250;
  const R = 6371, r = Math.PI / 180;
  const dLat = (B[0] - A[0]) * r, dLon = (B[1] - A[1]) * r;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(A[0] * r) * Math.cos(B[0] * r) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
};
const roadKm = (a, b) => (a === b ? 0 : Math.max(15, Math.round(geoKm(a, b) * 1.3)));

// Cities on the way: close to the straight line between origin and destination.
const routeWaypoints = (from, to) => {
  const direct = geoKm(from, to);
  const mids = Object.keys(CITY_COORDS)
    .filter(c => c !== from && c !== to)
    .map(c => ({ c, d1: geoKm(from, c), d2: geoKm(c, to) }))
    .filter(x => x.d1 + x.d2 < direct * 1.18 && x.d1 > 15 && x.d2 > 15)
    .sort((x, y) => x.d1 - y.d1)
    .slice(0, 3)
    .map(x => x.c);
  const list = [from, ...mids, to];
  const total = roadKm(from, to) || 1;
  let acc = 0;
  return list.map((c, i) => {
    if (i > 0) acc += roadKm(list[i - 1], c);
    return { city: c, km: i === list.length - 1 ? total : Math.min(total - 1, Math.round(acc * total / Math.max(1, list.slice(1).reduce((s, x, j) => s + roadKm(list[j], x), 0)))) };
  });
};

// ─── Tariff: fixed price per DUT, whatever the route or the cargo ─────
// 10 EUR, collected in GNF at the reference rate below (adjust if needed).
const TARIFF = { priceEur: 10, eurToGnf: 10000 };
TARIFF.priceGnf = TARIFF.priceEur * TARIFF.eurToGnf;
const UNIT_TONNES = { 'tonnes': 1, 't': 1, 'sacs 50kg': 0.05, 'sacs': 0.05, 'litres': 0.00085, 'fûts': 0.2, 'caisses': 0.03, 'kg': 0.001, 'cartons': 0.02 };
const toTonnes = (qty, unit) => +(qty * (UNIT_TONNES[unit] ?? 1)).toFixed(2);
const computeFee = ({ from, to }) => ({ km: roadKm(from, to), total: TARIFF.priceGnf, eur: TARIFF.priceEur });
const fmtEur = (n) => `${n} €`;
const fmtPrice = (gnf) => `${fmtGNF(gnf)} (${fmtEur(Math.round(gnf / TARIFF.eurToGnf))})`;

