const DEMO_BASE = new Date(2026, 3, 30, 9, 38, 0).getTime();
const demoNow = () => DEMO_BASE + (Date.now() - DEMO_T0);
const DAY = 86400000, MIN = 60000;
const at = (d, h = 9, m = 0) => new Date(2026, 3, d, h, m).getTime();
const pad2 = (n) => String(n).padStart(2, '0');
const fmtD = (ms) => { const d = new Date(ms); return `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}/${d.getFullYear()}`; };
const fmtT = (ms) => { const d = new Date(ms); return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`; };
const fmtDT = (ms) => `${fmtD(ms)}, ${fmtT(ms)}`;
const fmtAgo = (ms) => {
  const s = Math.max(0, Math.round((demoNow() - ms) / 1000));
  if (s < 60) return `il y a ${s} s`;
  if (s < 3600) return `il y a ${Math.round(s / 60)} min`;
  if (s < 86400) return `il y a ${Math.round(s / 3600)} h`;
  return `le ${fmtD(ms)}`;
};
